<a class="back-link" href="<?= BASE_URL ?>/index.php?page=produits">← Retour à l’inventaire</a><div class="form-layout"><section class="panel form-panel"><p class="eyebrow">FICHE RÉFÉRENCE</p><h2><?= e($pageTitle) ?></h2><form method="post" action="<?= BASE_URL ?>/index.php?page=produit-save" class="data-form"><input type="hidden" name="id" value="<?= e($product['id'] ?? '') ?>"><label>Nom de la pièce<input required name="nom" value="<?= e($product['nom'] ?? '') ?>"></label><label>Référence / SKU<input required name="sku" value="<?= e($product['sku'] ?? '') ?>" placeholder="Ex. HJ-FLT-001"></label><div class="form-grid"><label>Catégorie<select name="category_id"><option value="">Sans catégorie</option><?php foreach ($categories as $category): ?><option value="<?= e($category['id']) ?>" <?= ($product['category_id'] ?? '') == $category['id'] ? 'selected' : '' ?>><?= e($category['nom']) ?></option><?php endforeach; ?></select></label><label>Emplacement<input name="emplacement" value="<?= e($product['emplacement'] ?? '') ?>" placeholder="Rayon A3"></label></div><div class="form-grid"><label>Quantité<input required type="number" min="0" step="1" name="quantite" value="<?= e($product['quantite'] ?? 0) ?>"></label><label>Prix d’achat<input required type="number" min="0" step="0.01" name="prix_achat" value="<?= e($product['prix_achat'] ?? '0.00') ?>"></label></div><label>Prix de vente<input required type="number" min="0" step="0.01" name="prix_vente" value="<?= e($product['prix_vente'] ?? '0.00') ?>"></label><div class="form-actions"><a class="button button-ghost" href="<?= BASE_URL ?>/index.php?page=produits">Annuler</a><button class="button button-primary" type="submit">Enregistrer la référence</button></div></form></section><aside class="side-note"><span class="note-mark">i</span><h3>Règle de stock</h3><p>Une quantité inférieure à <?= STOCK_LOW_THRESHOLD ?> est signalée comme stock faible. Une quantité à zéro devient une rupture.</p></aside></div>
